<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserWebauthnCredential\Domain\ValueObject\UserWebauthnCredentialUserVO;
use Civi\Lughauth\Features\Access\User\Domain\UserRef;

trait UserWebauthnCredentialUserAccessor
{
    private UserWebauthnCredentialUserVO $_user;
    public function getUser(): UserRef
    {
        return $this->_user->value();
    }
    public function user(): UserWebauthnCredentialUserVO
    {
        return $this->_user;
    }
    public function isUserChanged(?self $original = null): bool
    {
        return !$this->_user->equals($original?->_user);
    }
    public function withUser(UserWebauthnCredentialUserVO|UserRef $user): self
    {
        $copy = clone $this;
        $copy->_user = UserWebauthnCredentialUserVO::from($user);
        return $copy;
    }
}
